//! Calls: Abdication's whistled Calls as an effect. Sparse, phrased whistles
//! sweeping between harmonics of the notes played (MIDI, a caller per note)
//! or of Root, through an echo into a reverb, added to whatever comes in. No
//! editor: the host shows the parameters.
//!
//! The callers and the reverb are Faust DSPs in ../dsp, compiled to Rust
//! (`calls_dsp.rs`, `reverb_dsp.rs`, generated by tools/gen-rust.sh: don't
//! edit them by hand); the echo between them is Rust (`echo`), so its time
//! can follow the host's tempo.

pub mod callers;
pub mod echo;
mod faust;
pub mod notes;

mod calls_dsp {
    #![allow(warnings, clippy::all)]
    use faust_types::*;
    include!("calls_dsp.rs");
}

mod reverb_dsp {
    #![allow(warnings, clippy::all)]
    use faust_types::*;
    include!("reverb_dsp.rs");
}

use std::num::NonZeroU32;
use std::sync::Arc;

use faust_types::{FaustDsp, ParamIndex};
use nih_plug::prelude::*;

use calls_dsp::CallsDsp;
use callers::{Callers, MAX_CALLERS};
use echo::{Division, Echo, EchoSettings};
use faust::Labels;
use notes::Source;
use reverb_dsp::ReverbDsp;

// ---------------------------------------------------------------------------
// Settings and parameters
// ---------------------------------------------------------------------------

/// Everything the sound is set from, as plain values (the parameters read
/// into it; tests build it directly). The defaults are Abdication's calls
/// (its Echo at half: a send of 0.25 and 45 % feedback, at 0.36 and 0.48 s;
/// its reverb), and the parameters' defaults.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Settings {
    /// The calls' level, dB.
    pub level: f32,
    pub activity: f32,
    pub rate: f32,
    pub follow: f32,
    pub width: f32,
    pub echo: f32,
    pub feedback: f32,
    pub echo_damp: f32,
    pub sync: bool,
    /// Each side's echo in ms, when not synced.
    pub time: [f32; 2],
    /// Each side's echo, when synced.
    pub division: [Division; 2],
    pub reverb: f32,
    pub decay: f32,
    pub damp: f32,
    pub predelay: f32,
}

impl Default for Settings {
    fn default() -> Self {
        Self { level: -24.0, activity: 0.45, rate: 1.0, follow: 1.0, width: 1.0, echo: 0.25, feedback: 0.45,
               echo_damp: 20_000.0, sync: false, time: [360.0, 480.0], division: [Division::D8D, Division::D4],
               reverb: 1.0, decay: 5.0, damp: 2500.0, predelay: 30.0 }
    }
}

impl Settings {
    fn echo_at(&self, tempo: f64) -> EchoSettings {
        let seconds = if self.sync {
            self.division.map(|d| d.seconds(tempo))
        } else {
            self.time.map(|ms| ms / 1000.0)
        };
        EchoSettings { send: self.echo, feedback: self.feedback, seconds, damp_hz: self.echo_damp }
    }
}

fn float(name: &str, default: f32, range: FloatRange, unit: &'static str, digits: usize) -> FloatParam {
    FloatParam::new(name, default, range)
        .with_unit(unit)
        .with_value_to_string(formatters::v2s_f32_rounded(digits))
}

fn linear(min: f32, max: f32) -> FloatRange {
    FloatRange::Linear { min, max }
}

fn skewed(min: f32, max: f32) -> FloatRange {
    FloatRange::Skewed { min, max, factor: FloatRange::skew_factor(-1.5) }
}

fn percent(name: &str, default: f32, max: f32) -> FloatParam {
    FloatParam::new(name, default, linear(0.0, max))
        .with_unit(" %")
        .with_value_to_string(formatters::v2s_f32_percentage(0))
        .with_string_to_value(formatters::s2v_f32_percentage())
}

fn hz(name: &str, default: f32, min: f32, max: f32) -> FloatParam {
    FloatParam::new(name, default, skewed(min, max))
        .with_value_to_string(formatters::v2s_f32_hz_then_khz(1))
        .with_string_to_value(formatters::s2v_f32_hz_then_khz())
}

#[derive(Params)]
pub struct CallsParams {
    /// Root, or the MIDI notes routed to the plugin, a caller each (Root until one arrives).
    #[id = "source"]
    pub source: EnumParam<Source>,
    #[id = "root"]
    pub root: IntParam,
    #[id = "level"]
    pub level: FloatParam,
    /// How often a phrase comes: 0 about a minute apart, 1 about half a second.
    #[id = "activity"]
    pub activity: FloatParam,
    /// The phrasing's speed.
    #[id = "rate"]
    pub rate: FloatParam,
    /// 0 the calls run on their own; 1 they sound only while the input does.
    #[id = "follow"]
    pub follow: FloatParam,
    /// How far apart the calls sit (a place each note).
    #[id = "width"]
    pub width: FloatParam,
    /// Into the echo.
    #[id = "echo"]
    pub echo: FloatParam,
    #[id = "feedback"]
    pub feedback: FloatParam,
    /// The lowpass in the echo's loop: each repeat darker.
    #[id = "echo_damp"]
    pub echo_damp: FloatParam,
    /// The echo's times follow the tempo (the divisions), or not (the ms).
    #[id = "sync"]
    pub sync: BoolParam,
    #[id = "time_l"]
    pub time_l: FloatParam,
    #[id = "time_r"]
    pub time_r: FloatParam,
    #[id = "div_l"]
    pub div_l: EnumParam<Division>,
    #[id = "div_r"]
    pub div_r: EnumParam<Division>,
    /// 1 the calls and their echo are heard only through the reverb, 0 dry.
    #[id = "reverb"]
    pub reverb: FloatParam,
    #[id = "decay"]
    pub decay: FloatParam,
    /// Where the reverb's highs start to die faster.
    #[id = "damp"]
    pub damp: FloatParam,
    #[id = "predelay"]
    pub predelay: FloatParam,
}

impl Default for CallsParams {
    fn default() -> Self {
        let d = Settings::default();
        let ms = |name: &str, default: f32| {
            float(name, default, skewed(10.0, echo::MAX_SECONDS * 1000.0), " ms", 0)
        };
        Self {
            source: EnumParam::new("Source", Source::Midi),
            root: notes::root_param(48),
            level: float("Level", d.level, linear(-60.0, 0.0), " dB", 1),
            activity: percent("Activity", d.activity, 1.0),
            rate: float("Rate", d.rate, linear(0.25, 3.0), "x", 2),
            follow: percent("Follow", d.follow, 1.0),
            width: percent("Width", d.width, 1.0),
            echo: percent("Echo", d.echo, 1.0),
            feedback: percent("Feedback", d.feedback, 0.95),
            echo_damp: hz("Echo Damp", d.echo_damp, 500.0, 20_000.0),
            sync: BoolParam::new("Sync", d.sync),
            time_l: ms("Time L", d.time[0]),
            time_r: ms("Time R", d.time[1]),
            div_l: EnumParam::new("Division L", d.division[0]),
            div_r: EnumParam::new("Division R", d.division[1]),
            reverb: percent("Reverb", d.reverb, 1.0),
            decay: float("Decay", d.decay, skewed(0.5, 20.0), " s", 1),
            damp: hz("Damp", d.damp, 1000.0, 12_000.0),
            predelay: float("Pre-Delay", d.predelay, linear(0.0, 150.0), " ms", 0),
        }
    }
}

impl CallsParams {
    pub fn settings(&self) -> Settings {
        Settings {
            level: self.level.value(),
            activity: self.activity.value(),
            rate: self.rate.value(),
            follow: self.follow.value(),
            width: self.width.value(),
            echo: self.echo.value(),
            feedback: self.feedback.value(),
            echo_damp: self.echo_damp.value(),
            sync: self.sync.value(),
            time: [self.time_l.value(), self.time_r.value()],
            division: [self.div_l.value(), self.div_r.value()],
            reverb: self.reverb.value(),
            decay: self.decay.value(),
            damp: self.damp.value(),
            predelay: self.predelay.value(),
        }
    }
}

// ---------------------------------------------------------------------------
// The sound
// ---------------------------------------------------------------------------

/// The callers' Faust controls the settings set one to one, and the reverb's.
const CALLS_CONTROLS: [&str; 5] = ["level", "activity", "rate", "follow", "width"];
const REVERB_CONTROLS: [&str; 4] = ["mix", "decay", "damp", "predelay"];

type Block = Vec<f32>;

/// Callers, echo and reverb, added to the input.
pub struct Voice {
    calls: Box<CallsDsp>,
    echo: Echo,
    reverb: Box<ReverbDsp>,
    seed: ParamIndex,
    notes: [ParamIndex; MAX_CALLERS],
    gates: [ParamIndex; MAX_CALLERS],
    calls_controls: [ParamIndex; CALLS_CONTROLS.len()],
    reverb_controls: [ParamIndex; REVERB_CONTROLS.len()],
    settings: Settings,
    tempo: f64,
    /// The calls, their echo, and the two summed then through the reverb.
    calls_out: [Block; 2],
    echo_out: [Block; 2],
    wet: [Block; 2],
}

impl Voice {
    pub fn new(sample_rate: f32, max_block: usize, seed: u32) -> Self {
        let labels = Labels::of::<CallsDsp>();
        let reverb_labels = Labels::of::<ReverbDsp>();
        let mut calls = Box::new(CallsDsp::new());
        calls.init(sample_rate as i32);
        let mut reverb = Box::new(ReverbDsp::new());
        reverb.init(sample_rate as i32);
        let block = || [vec![0.0; max_block], vec![0.0; max_block]];
        let mut v = Self {
            calls,
            echo: Echo::new(sample_rate),
            reverb,
            seed: labels.get("seed"),
            notes: std::array::from_fn(|k| labels.get(&format!("note{k}"))),
            gates: std::array::from_fn(|k| labels.get(&format!("gate{k}"))),
            calls_controls: CALLS_CONTROLS.map(|c| labels.get(c)),
            reverb_controls: REVERB_CONTROLS.map(|c| reverb_labels.get(c)),
            settings: Settings::default(),
            tempo: 120.0,
            calls_out: block(),
            echo_out: block(),
            wet: block(),
        };
        v.reseed(seed);
        v
    }

    /// A fresh start on its own random streams (read on the first sample),
    /// with no tails.
    pub fn reseed(&mut self, seed: u32) {
        self.calls.instance_clear();
        self.reverb.instance_clear();
        self.echo.clear();
        self.calls.set_param(self.seed, (seed % 1_000_000) as f32);
    }

    pub fn set(&mut self, settings: &Settings, tempo: f64, gates: &[(f32, bool); MAX_CALLERS]) {
        self.settings = *settings;
        self.tempo = tempo;
        let s = settings;
        for (c, v) in self.calls_controls.iter().zip([s.level, s.activity, s.rate, s.follow, s.width]) {
            self.calls.set_param(*c, v);
        }
        for (c, v) in self.reverb_controls.iter().zip([s.reverb, s.decay, s.damp, s.predelay]) {
            self.reverb.set_param(*c, v);
        }
        for (k, (hz, on)) in gates.iter().enumerate() {
            self.calls.set_param(self.notes[k], *hz);
            self.calls.set_param(self.gates[k], *on as u8 as f32);
        }
    }

    /// `output` is `input` with the calls added. At most `max_block` samples.
    pub fn compute(&mut self, input: [&[f32]; 2], output: [&mut [f32]; 2]) {
        let n = input[0].len();
        let [cl, cr] = &mut self.calls_out;
        self.calls.compute(n as i32, &input, &mut [&mut cl[..n], &mut cr[..n]]);
        let [el, er] = &mut self.echo_out;
        self.echo.process(&self.settings.echo_at(self.tempo), [&cl[..n], &cr[..n]], [&mut el[..n], &mut er[..n]]);
        // The reverb takes the calls and their echo together.
        for side in 0..2 {
            for (c, e) in self.calls_out[side][..n].iter_mut().zip(&self.echo_out[side][..n]) {
                *c += e;
            }
        }
        let [cl, cr] = &self.calls_out;
        let [wl, wr] = &mut self.wet;
        self.reverb.compute(n as i32, &[&cl[..n], &cr[..n]], &mut [&mut wl[..n], &mut wr[..n]]);
        let [ol, or] = output;
        for (side, out) in [ol, or].into_iter().enumerate() {
            for ((o, i), w) in out[..n].iter_mut().zip(&input[side][..n]).zip(&self.wet[side][..n]) {
                *o = i + w;
            }
        }
    }
}

/// A seed for an instance: different each time one is made.
fn fresh_seed() -> u32 {
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.subsec_nanos());
    nanos ^ (&nanos as *const u32 as usize as u32).rotate_left(13)
}

// ---------------------------------------------------------------------------
// The plugin
// ---------------------------------------------------------------------------

pub struct Calls {
    params: Arc<CallsParams>,
    voice: Option<Voice>,
    callers: Callers,
    /// The input, copied: the output is written in place.
    input: [Vec<f32>; 2],
}

impl Default for Calls {
    fn default() -> Self {
        Self { params: Arc::new(CallsParams::default()), voice: None, callers: Callers::default(),
               input: [Vec::new(), Vec::new()] }
    }
}

impl Plugin for Calls {
    const NAME: &'static str = "Calls";
    const VENDOR: &'static str = "Abdicant";
    const URL: &'static str = "";
    const EMAIL: &'static str = "";
    const VERSION: &'static str = env!("CARGO_PKG_VERSION");

    const AUDIO_IO_LAYOUTS: &'static [AudioIOLayout] = &[AudioIOLayout {
        main_input_channels: NonZeroU32::new(2),
        main_output_channels: NonZeroU32::new(2),
        ..AudioIOLayout::const_default()
    }];
    const MIDI_INPUT: MidiConfig = MidiConfig::Basic;

    type SysExMessage = ();
    type BackgroundTask = ();

    fn params(&self) -> Arc<dyn Params> {
        self.params.clone()
    }

    fn initialize(&mut self, _: &AudioIOLayout, config: &BufferConfig, _: &mut impl InitContext<Self>) -> bool {
        let n = config.max_buffer_size as usize;
        self.voice = Some(Voice::new(config.sample_rate, n, fresh_seed()));
        self.input = [vec![0.0; n], vec![0.0; n]];
        true
    }

    fn reset(&mut self) {
        self.callers.clear();
        if let Some(v) = self.voice.as_mut() {
            v.reseed(fresh_seed());
        }
    }

    fn process(&mut self, buffer: &mut Buffer, _: &mut AuxiliaryBuffers, context: &mut impl ProcessContext<Self>) -> ProcessStatus {
        let Some(voice) = self.voice.as_mut() else { return ProcessStatus::Normal };
        while let Some(event) = context.next_event() {
            match event {
                NoteEvent::NoteOn { note, .. } => self.callers.note_on(note),
                NoteEvent::NoteOff { note, .. } => self.callers.note_off(note),
                _ => {}
            }
        }
        let p = &self.params;
        let tempo = context.transport().tempo.unwrap_or(120.0);
        voice.set(&p.settings(), tempo, &self.callers.gates(p.source.value(), p.root.value()));

        let n = buffer.samples();
        let channels = buffer.as_slice();
        if channels.len() < 2 || n > self.input[0].len() {
            return ProcessStatus::Normal;
        }
        for (copy, channel) in self.input.iter_mut().zip(channels.iter()) {
            copy[..n].copy_from_slice(&channel[..n]);
        }
        let (left, rest) = channels.split_at_mut(1);
        voice.compute([&self.input[0][..n], &self.input[1][..n]], [&mut left[0][..n], &mut rest[0][..n]]);
        // Calls come and go on their own: keep it running.
        ProcessStatus::KeepAlive
    }
}

